contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // send amount to c.play; must ensure this contract has enough balance to forward it
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe before-values
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balCBefore = address(c).balance;
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;

        // call play and record whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balCAfter = address(c).balance;
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;

        // General invariant to hold for all inputs: If call did not revert and amount equals ticket price (10), then:
        // either (A) pot increased by amount and contract balance increased by amount;
        // or (B) pot became zero and the contract's balance decreased by at least potBefore - 1 (fee).
        // We express (B) as: potAfter == 0 && balCBefore + amount >= balCAfter + (potBefore - 1)
        // (rearranged to avoid underflow inside assert and use only public observables).

        assert(
            reverted || (amount == 10 && (
                (potAfter == potBefore + amount && balCAfter == balCBefore + amount)
                ||
                (potAfter == 0 && balCBefore + amount >= balCAfter + (potBefore - 1))
            ))
        );
    }

    receive() external payable {}
}

